            Legume, // 콩류
            Nut, // 견과류
            Herb, // 허브
            Spice, // 향신료
            Drink, // 음료류
            // 어류 (fish_cat)
            Salmon, // 연어·송어류
            BlueFish, // 등푸른 해양어
            FlatFish, // 넙치·가자미류
            Catfish, // 메기류
            Carp, // 잉어·붕어류
            SmallFresh, // 소형 민물어
            Eel, // 장어류
            // 몬스터 (mon_cat)
            RegularMeat, // 보통 육류
            Reptile, // 파충류·용
            Poultry, // 조류·익룡
            Slime, // 점액·피·액체
            Flesh, // 살점·잔해
            Mystic, // 영묘·뿔·비늘
        }

